<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090b10;
        --panel: #111722;
        --panel-strong: #161f2d;
        --text: #f7f8fb;
        --muted: #a9b3c4;
        --danger: #ff4d6d;
        --danger-strong: #e93659;
        --border: rgba(255, 255, 255, 0.12);
        --shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 2rem;
        background:
          radial-gradient(circle at top left, rgba(91, 124, 250, 0.2), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(255, 77, 109, 0.14), transparent 32rem),
          var(--bg);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }

      main {
        width: min(100%, 54rem);
      }

      .preview-card {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.03));
        box-shadow: var(--shadow);
      }

      .image-frame {
        padding: 1rem;
        background: #05070b;
      }

      .image-frame img {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        border-radius: 1rem;
        object-fit: cover;
      }

      .preview-content {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.25rem;
      }

      h1,
      p {
        margin: 0;
      }

      h1 {
        font-size: clamp(1.5rem, 3vw, 2.25rem);
        letter-spacing: -0.04em;
      }

      .preview-content p {
        margin-top: 0.35rem;
        color: var(--muted);
      }

      button {
        min-height: 2.75rem;
        border: 0;
        border-radius: 999px;
        padding: 0.75rem 1.1rem;
        color: var(--text);
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition:
          transform 160ms ease,
          background-color 160ms ease,
          box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus-visible {
        outline: 3px solid #8fb3ff;
        outline-offset: 3px;
      }

      .trigger {
        flex: 0 0 auto;
        background: linear-gradient(135deg, var(--danger), var(--danger-strong));
        box-shadow: 0 12px 30px rgba(255, 77, 109, 0.28);
      }

      .dialog-backdrop {
        position: fixed;
        inset: 0;
        display: none;
        place-items: center;
        padding: 1rem;
        background: rgba(0, 0, 0, 0.72);
        backdrop-filter: blur(12px);
      }

      .dialog-backdrop.is-open {
        display: grid;
      }

      .dialog {
        width: min(100%, 30rem);
        border: 1px solid var(--border);
        border-radius: 1.4rem;
        padding: 1.5rem;
        background: linear-gradient(180deg, var(--panel-strong), var(--panel));
        box-shadow: var(--shadow);
      }

      .dialog h2 {
        margin: 0;
        font-size: 1.45rem;
        letter-spacing: -0.03em;
      }

      .dialog p {
        margin-top: 0.75rem;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      .button-secondary {
        background: rgba(255, 255, 255, 0.1);
      }

      .button-secondary:hover {
        background: rgba(255, 255, 255, 0.16);
      }

      .button-danger {
        background: var(--danger-strong);
      }

      .button-danger:hover {
        background: #d42f50;
      }

      @media (max-width: 38rem) {
        body {
          padding: 1rem;
        }

        .preview-content,
        .dialog-actions {
          align-items: stretch;
          flex-direction: column;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <article class="preview-card" aria-labelledby="image-title">
        <div class="image-frame">
          <img
            src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&amp;fit=crop&amp;w=1400&amp;q=80"
            alt="A quiet lakeside cabin surrounded by trees at sunrise"
          >
        </div>
        <div class="preview-content">
          <div>
            <h1 id="image-title">Lakeside Cabin</h1>
            <p>Saved in your travel inspiration library.</p>
          </div>
          <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
            Delete image
          </button>
        </div>
      </article>
    </main>

    <div class="dialog-backdrop" id="dialog-backdrop">
      <section
        class="dialog"
        id="delete-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="dialog-title"
        aria-describedby="dialog-description"
      >
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-description">
          This will remove “Lakeside Cabin” from your library. This action cannot be undone.
        </p>
        <div class="dialog-actions">
          <button class="button-secondary" type="button" data-close-dialog>Cancel</button>
          <button class="button-danger" type="button" data-confirm-delete>Delete image</button>
        </div>
      </section>
    </div>

    <script>
      const trigger = document.querySelector(".trigger");
      const backdrop = document.querySelector("#dialog-backdrop");
      const dialog = document.querySelector("#delete-dialog");
      const closeButton = document.querySelector("[data-close-dialog]");
      const confirmButton = document.querySelector("[data-confirm-delete]");
      let lastFocusedElement = null;

      function getFocusableElements() {
        return Array.from(
          dialog.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')
        ).filter((element) => !element.hasAttribute("disabled"));
      }

      function openDialog() {
        lastFocusedElement = document.activeElement;
        backdrop.classList.add("is-open");
        closeButton.focus();
      }

      function closeDialog() {
        backdrop.classList.remove("is-open");

        if (lastFocusedElement) {
          lastFocusedElement.focus();
        }
      }

      trigger.addEventListener("click", openDialog);
      closeButton.addEventListener("click", closeDialog);
      confirmButton.addEventListener("click", closeDialog);

      backdrop.addEventListener("click", (event) => {
        if (event.target === backdrop) {
          closeDialog();
        }
      });

      document.addEventListener("keydown", (event) => {
        if (!backdrop.classList.contains("is-open")) {
          return;
        }

        if (event.key === "Escape") {
          closeDialog();
          return;
        }

        if (event.key !== "Tab") {
          return;
        }

        const focusableElements = getFocusableElements();
        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (event.shiftKey && document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        } else if (!event.shiftKey && document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      });
    </script>
  </body>
</html>
